insert into cisco.cisco_decks (id, slug, title, sermon_id, metadata)
insert into cisco.cisco_slides (deck_id, position, html, outline_html, bg, notes)
values
  ('c1000000-0000-4000-8000-000000000004', 1, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20">', '<p><strong>The Obvious</strong> — the key to transformation is right under our nose. Title up; hold through the welcome.</p>', null, 'Title is on the background. Hold through the welcome.'),
  ('c1000000-0000-4000-8000-000000000004', 2, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm stage" data-stage="1">Sometimes the most difficult things to see are not the things that are hidden.</h2><h2 class="sm stage" data-stage="2">They''re the things that become all too familiar.</h2></div>', '<p>It''s strange how easily we can overlook the events of transformation simply because we stare at them every day. Sometimes the most difficult things to see are not the things that are hidden — they''re the things that become all too familiar.</p>', null, 'One click — second line lands on its own.'),
  ('c1000000-0000-4000-8000-000000000004', 3, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm stage" data-stage="1">What if one of our biggest problems isn''t what we don''t have?</h2><h2 class="sm stage" data-stage="2">What if we''re overlooking what God has already put right in front of us?</h2></div>', '<p>We spend a lot of time thinking about what we need but don''t have. The hidden belief: transformation is expensive — more money, more people, more talent, more opportunities, more resources.</p><p><strong>What if one of our biggest problems isn''t what we don''t have? What if we''re overlooking what God has already put right in front of us?</strong> How can something be right in front of us every day — and we never see what it could become?</p>', null, 'One click — the second question lands on its own.'),
  ('c1000000-0000-4000-8000-000000000004', 4, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><p class="kicker">The question we rarely ask</p><div class="rule-line"></div><blockquote>How could God use this for His purpose?</blockquote></div>', '<p><strong>How do we miss what''s right in front of us?</strong> We buy technology and immediately learn how it can entertain us. We discover a new restaurant and think about eating there. We get a new vehicle and think about where we can go. We meet somebody new and look for what we have in common. Nothing wrong with any of that — but there''s another question we rarely ask: <strong>how could God use this for His purpose?</strong> Is it possible the place to start is just using what we already have?</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 5, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">Moses told the Israelites: &ldquo;Look around, people.&rdquo;</h2><p class="sub">Deuteronomy 6:4&ndash;9</p></div>', '<p><strong>Read Deuteronomy 6:4–9.</strong> Background to Deuteronomy — Moses wasn''t merely giving them information. He''s teaching them to build a new perspective.</p>', null, 'Read the passage before advancing.'),
  ('c1000000-0000-4000-8000-000000000004', 6, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><blockquote>&ldquo;These commandments that I give you today are to be on your hearts.&rdquo;</blockquote><p class="ref">Deuteronomy 6:6</p></div>', '<p><strong>Destination — the heart. The means</strong> — doorpost, hand, forehead, conversations, morning, evening, and roadway. Don''t confine God''s Word to one religious moment. Surround yourself with reminders of it. Build it into your day, your house, your relationships, the raising of your children.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 7, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">Make the Word of God part of the architecture of your life.</h2></div>', '<p>This wasn''t "remember to have a Bible lesson occasionally." It was much bigger: <strong>make the Word of God part of the architecture of your life.</strong> Israel now possessed God''s revealed instruction in a form that could be remembered, taught, repeated, written, displayed, and deliberately passed from one generation to another.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 8, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><p class="kicker">Look around</p><div class="rule-line"></div><ul><li>Your house? <strong>Use it.</strong></li><li>Your doorway? <strong>Use it.</strong></li><li>Your conversations with your children? <strong>Use them.</strong></li><li>Walking down the road? <strong>Use that.</strong></li><li>Waking up? Going to bed? <strong>Use that.</strong></li></ul></div>', '<p><strong>Moses isn''t pointing them toward some extraordinary resource.</strong> He''s saying: look around. There''s a door — write it there. You have children — talk to them. You''re going somewhere — talk about it while you''re walking. Sitting around the house — talk about it there. Getting ready for bed — there''s another opportunity. Waking up — there''s another one.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 9, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">Turn ordinary events into a delivery system for the Word of God.</h2></div>', '<p><strong>Moses is calling on us to turn ordinary events into a DELIVERY SYSTEM for the Word of God.</strong></p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 10, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm stage" data-stage="1">None of those events were new.</h2><h2 class="sm stage" data-stage="2">What Moses changed was the purpose attached to them.</h2></div>', '<p><strong>The question nobody is asking: why would Moses have to tell them this?</strong> He''s commanding something that apparently wasn''t happening automatically. They had doors before Moses mentioned doorposts. They had homes. Children. Conversations. They walked the roads, woke up, went to sleep. None of those events were new — <strong>what Moses changed was the purpose attached to them.</strong></p>', null, 'One click — second line lands on its own.'),
  ('c1000000-0000-4000-8000-000000000004', 11, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm stage" data-stage="1">Maybe our greatest Kingdom problem isn''t that we don''t have enough resources.</h2><h2 class="sm stage" data-stage="2">Maybe we haven''t learned to see the Kingdom possibilities in the resources we already have.</h2></div>', '<p>Maybe our greatest Kingdom problem isn''t that we don''t have enough resources. Maybe we just haven''t learned how to see the Kingdom possibilities in the resources we already have.</p>', null, 'One click — second line lands on its own.'),
  ('c1000000-0000-4000-8000-000000000004', 12, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><p class="kicker">Obvious questions</p><div class="rule-line"></div><ul><li>What do I already have?</li><li>Who do I already know?</li><li>Where do I already go?</li><li>What am I already good at?</li><li>What conversations am I already having?</li></ul></div>', '<p><strong>Obvious questions:</strong> What do I already have? Who do I already know? Where do I already go? What am I already good at? What technology am I already using? What conversations am I already having? At what places am I already hanging out?</p><p>Moses wanted Israel to build habits that would keep them seeing it over and over — because whatever isn''t deliberately built into our lives eventually gets crowded out by everything that is. God didn''t give Israel new things to do. He gave them new reasons.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 13, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">The danger was walking into abundance and going blind.</h2></div>', '<p>The danger wasn''t scarcity. The danger wasn''t the enemy. The danger wasn''t the wilderness. <strong>The danger was walking into abundance and going blind.</strong> The solution: create new habits.</p><p><strong>Our habits reveal what gets our best</strong> — and they explain why we overlook the obvious. Nobody reminds us to check our phones. We don''t need a discipleship class to teach us to open Facebook. Nobody calls me Thursday afternoon: "Joe, remember, you''re supposed to eat supper tonight."</p>', null, 'The supper line is the laugh — let it land.'),
  ('c1000000-0000-4000-8000-000000000004', 14, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">Has the Kingdom become something we believe in without becoming something we build our lives around?</h2></div>', '<p>Our lives naturally organize themselves around things we have decided matter. And that''s where the uncomfortable question creeps in: <strong>has the Kingdom become something we believe in without it becoming something we build our lives around?</strong> Present in belief but absent in life.</p><p>Moses is saying: build habits that keep God from becoming peripheral. There''s an idea in leadership called a <strong>keystone habit</strong> — one small habit that begins influencing other areas of your life (floss → "I''m disciplined" → kiss the wife → wake up ready). Moses understood that long ago: not "once a year, have a big spiritual event" — when you get up, talk about it; around the house, talk about it; traveling, going to bed, talk about it. <strong>Attach the things of God to things you''re already doing.</strong> One small, repeated habit can change the environment of an entire life — transformation.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 15, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><blockquote>&ldquo;Don''t live the way this world lives. Let your way of thinking be completely changed.&rdquo;</blockquote><p class="ref">Romans 12:2 (NIrV)</p></div>', '<p><strong>Romans 12:2 (NIrV):</strong> "Don''t live the way this world lives. Let your way of thinking be completely changed. Then you will be able to test what God wants for you. And you will agree that what he wants is right. His plan is good and pleasing and perfect." Paul taught that true transformation comes from God by changing how you think.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 16, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><p class="kicker">One question</p><div class="rule-line"></div><blockquote>How can I use this moment for the Kingdom?</blockquote></div>', '<p><strong>Imagine if we started asking one question.</strong> What if for the next week you developed one new keystone habit — every time you pick up something, walk into some place, meet somebody: <strong>"How can I use this moment for the Kingdom?"</strong></p><p>Bought a car? New computer? Love drinking coffee somewhere every morning? Good at woodworking? Have a home? Know how to make videos? An awesome cook — who could sit around your table? Maybe that''s the event that makes a difference for God''s Kingdom.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 17, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">Don''t miss what God can do through something you''ve stopped noticing.</h2></div>', '<p><strong>Don''t miss what God can do through something you''ve stopped noticing.</strong> Some of our greatest Kingdom opportunities may be hiding in plain sight.</p><p>One last thought&hellip;</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 18, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">Don''t miss the handoff.</h2><p class="sub">Deuteronomy 6:20</p></div>', '<p><strong>Don''t miss the handoff.</strong> Immediately after the teaching instructions, Moses starts talking about children and future generations. "In the future, when your son asks you, ''What is the meaning of the stipulations, decrees and laws…?''" (Deut. 6:20) — you tell them what God did in Egypt.</p><p>Every generation inherits something from the generation before it. Every generation is teaching the generation behind it — even when it doesn''t realize it''s teaching. <strong>How are we helping the next generation know, discover, and appreciate who God is?</strong></p><p>In 2026 we have phones, tablets, computers, social media, video, podcasts, coffee shops, vehicles, homes, workplaces, friendships, hobbies&hellip; The problem isn''t opportunity. We may have more ways to communicate than any generation in history — and still fail to communicate the thing that matters most.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 19, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm stage" data-stage="1">The last time God told Israel to put something on a doorframe, it was blood.</h2><h2 class="sm stage" data-stage="2">And it was the difference between life and death.</h2></div>', '<p>Imagine where the Israelites stood&hellip; <strong>The last time God told Israel to put something on a doorframe, it was blood</strong> (Egypt). And it was the difference between life and death.</p>', null, 'One click — second line lands on its own. Slow down here.'),
  ('c1000000-0000-4000-8000-000000000004', 20, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><h2 class="sm">God has always done His most important work on ordinary doorways.</h2><p class="sub">Claim your doorway for the Kingdom.</p></div>', '<p><strong>God has always done His most important work on ordinary doorways.</strong> Claim your doorway for the Kingdom.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 21, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><blockquote>&ldquo;As for me and my house, we will serve the Lord.&rdquo;</blockquote><p class="ref">Joshua 24:15</p></div>', '<p>Near the end of his life, Joshua gathers Israel at Shechem and challenges them to give up foreign idols and choose whom they will follow: <strong>"As for me and my house, we will serve the Lord."</strong> (Joshua 24:15)</p><p>Are you ready to reclaim your doorpost for the Kingdom? Walks, restaurants, cars, mornings, nights&hellip;</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 22, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20"><div class="panel"><p class="kicker">The challenge</p><div class="rule-line"></div><ol><li>Start noticing the daily events where transformation is hidden.</li><li>Build one keystone habit for the Kingdom &mdash; and start seeing God appear in your life.</li></ol></div>', '<p><strong>Final challenge:</strong> 1) Start taking notice of the daily events where transformation is hidden. 2) Build one "keystone" habit for the Kingdom and start seeing God appear in your life.</p>', null, null),
  ('c1000000-0000-4000-8000-000000000004', 23, '<img class="slide-image drift" src="/sermons/the-obvious/bg.jpg" alt="The Obvious — Deuteronomy 6:4–9, 20">', '<p><strong>Title screen</strong> — invitation / closing prayer.</p>', null, 'Background only for the invitation.')
insert into cisco.cisco_deck_state (deck_id, current_slide, is_live, is_blank)
